SELECT
ps.*,
item.material_name AS packageName,
item.material_spec AS packageSpec
FROM mis_pricing_strategy ps
LEFT JOIN mis_material item ON ps.package_item_id = item.id



        AND ps.item_id = #{entity.itemId}


        AND ps.package_item_id = #{entity.packageItemId}


        AND ps.is_active = #{entity.isActive}


        AND ps.pricing_type=#{entity.pricingType}


       AND ps.salesman_id = #{entity.salesmanId}


       AND ps.customer_id = #{entity.customer_id}




        AND ps.item_code LIKE CONCAT('%', #{entity.itemCode}, '%')


        AND ps.item_name LIKE CONCAT('%', #{entity.itemName}, '%')


        AND ps.customer_name LIKE CONCAT('%', #{entity.customerName}, '%')


        AND ps.salesman_name LIKE CONCAT('%', #{entity.salesmanName}, '%')


        AND ps.strategy_name LIKE CONCAT('%', #{entity.strategyName}, '%')
